import React, { useRef, useEffect } from 'react';

// Much more dramatic orb — deep texture layers, inner glow, animated surface noise
export default function Orb3D({ size = 280, colors = ['#6040c0','#1a0a50','#9070e0'], speed = 0.4, morphing = true }) {
  const canvasRef = useRef(null);
  const raf = useRef(null);
  const t = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const dpr = window.devicePixelRatio || 1;
    canvas.width  = size * dpr;
    canvas.height = size * dpr;
    canvas.style.width  = size + 'px';
    canvas.style.height = size + 'px';
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);

    const draw = () => {
      t.current += 0.006 * speed;
      ctx.clearRect(0, 0, size, size);

      const cx = size / 2, cy = size / 2;
      const r  = size * 0.40;

      // ── Morphing path ──
      const buildPath = (radiusFn) => {
        ctx.beginPath();
        const pts = 80;
        for (let i = 0; i <= pts; i++) {
          const a  = (i / pts) * Math.PI * 2;
          const wr = radiusFn(a);
          const x  = cx + Math.cos(a) * wr;
          const y  = cy + Math.sin(a) * wr;
          i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
        }
        ctx.closePath();
      };

      const mainR = (a) => morphing
        ? r + Math.sin(a * 3 + t.current * 0.7)  * r * 0.06
            + Math.cos(a * 5 + t.current * 1.1)  * r * 0.025
            + Math.sin(a * 7 + t.current * 0.4)  * r * 0.015
        : r;

      // ── Outer ambient glow (drawn as circle, no clip) ──
      const glowGrad = ctx.createRadialGradient(cx, cy, r * 0.6, cx, cy, r * 1.8);
      glowGrad.addColorStop(0, `${colors[0]}30`);
      glowGrad.addColorStop(1, 'transparent');
      ctx.beginPath();
      ctx.arc(cx, cy, r * 1.8, 0, Math.PI * 2);
      ctx.fillStyle = glowGrad;
      ctx.fill();

      // ── Main sphere ──
      buildPath(mainR);
      ctx.save();
      ctx.clip();

      // Layer 1 — deep base
      const base = ctx.createRadialGradient(cx - r*0.1, cy - r*0.1, 0, cx, cy, r * 1.1);
      base.addColorStop(0,    colors[2] + 'ff');
      base.addColorStop(0.35, colors[0] + 'ff');
      base.addColorStop(0.75, colors[1] + 'ff');
      base.addColorStop(1,    '#080410ff');
      ctx.fillStyle = base;
      ctx.fillRect(0, 0, size, size);

      // Layer 2 — internal light (moves)
      const lx = cx + Math.sin(t.current * 0.6) * r * 0.3;
      const ly = cy + Math.cos(t.current * 0.5) * r * 0.2;
      const inner = ctx.createRadialGradient(lx, ly, 0, lx, ly, r * 0.9);
      inner.addColorStop(0,   'rgba(220,200,255,0.22)');
      inner.addColorStop(0.5, 'rgba(160,120,255,0.08)');
      inner.addColorStop(1,   'transparent');
      ctx.fillStyle = inner;
      ctx.fillRect(0, 0, size, size);

      // Layer 3 — surface noise simulation (multiple small blobs)
      for (let i = 0; i < 6; i++) {
        const bx = cx + Math.sin(t.current * 0.3 + i * 1.2) * r * 0.5;
        const by = cy + Math.cos(t.current * 0.4 + i * 0.9) * r * 0.45;
        const br = r * (0.18 + Math.sin(t.current + i) * 0.05);
        const bg = ctx.createRadialGradient(bx, by, 0, bx, by, br);
        bg.addColorStop(0, `rgba(255,240,255,0.06)`);
        bg.addColorStop(1, 'transparent');
        ctx.fillStyle = bg;
        ctx.fillRect(0, 0, size, size);
      }

      // Layer 4 — depth shadow bottom-right
      const shadow = ctx.createRadialGradient(cx + r*0.4, cy + r*0.45, 0, cx + r*0.4, cy + r*0.45, r * 0.9);
      shadow.addColorStop(0, 'rgba(0,0,0,0.55)');
      shadow.addColorStop(1, 'transparent');
      ctx.fillStyle = shadow;
      ctx.fillRect(0, 0, size, size);

      // Layer 5 — sharp specular highlight
      const hx = cx - r * (0.24 + Math.sin(t.current * 0.3) * 0.04);
      const hy = cy - r * (0.26 + Math.cos(t.current * 0.25) * 0.04);
      const spec = ctx.createRadialGradient(hx, hy, 0, hx, hy, r * 0.38);
      spec.addColorStop(0,    'rgba(255,255,255,0.55)');
      spec.addColorStop(0.25, 'rgba(255,255,255,0.12)');
      spec.addColorStop(0.6,  'rgba(255,255,255,0.02)');
      spec.addColorStop(1,    'transparent');
      ctx.fillStyle = spec;
      ctx.fillRect(0, 0, size, size);

      // Layer 6 — soft secondary highlight (opposite side)
      const sh2 = ctx.createRadialGradient(cx + r*0.22, cy + r*0.1, 0, cx + r*0.22, cy + r*0.1, r * 0.28);
      sh2.addColorStop(0, 'rgba(200,180,255,0.15)');
      sh2.addColorStop(1, 'transparent');
      ctx.fillStyle = sh2;
      ctx.fillRect(0, 0, size, size);

      ctx.restore();

      // ── Orbiting ring (outside sphere) ──
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(t.current * 0.25);
      ctx.scale(1, 0.28);
      ctx.beginPath();
      ctx.arc(0, 0, r * 1.18, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      ctx.lineWidth = 1.5;
      ctx.setLineDash([4, 9]);
      ctx.stroke();
      ctx.restore();

      // Second ring — opposite direction
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(-t.current * 0.15 + 1.0);
      ctx.scale(0.3, 1);
      ctx.beginPath();
      ctx.arc(0, 0, r * 1.22, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(255,255,255,0.05)';
      ctx.lineWidth = 1;
      ctx.setLineDash([3, 12]);
      ctx.stroke();
      ctx.restore();

      // ── Ground glow ──
      const gg = ctx.createRadialGradient(cx, cy + r * 0.88, 0, cx, cy + r * 0.88, r * 0.75);
      gg.addColorStop(0, colors[0] + '33');
      gg.addColorStop(1, 'transparent');
      ctx.beginPath();
      ctx.ellipse(cx, cy + r * 0.9, r * 0.7, r * 0.16, 0, 0, Math.PI * 2);
      ctx.fillStyle = gg;
      ctx.fill();

      raf.current = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(raf.current);
  }, [size, JSON.stringify(colors), speed, morphing]);

  return <canvas ref={canvasRef} style={{ display:'block', maxWidth:'100%' }} />;
}
